<?php
/** Plain-text login presentation; clinical identity and authentication remain separate. */
function login_copy_defaults():array{return ['title'=>'Website Management System','intro'=>'Klinik Kecantikan {nama_klinik}{daftar_cabang}','features'=>"Multi-cabang & hak akses berbasis role\nReservasi, rekam medis, dan order terhubung\nInventory & stok otomatis per cabang\nLaporan, dashboard, dan audit log",'footer'=>'© {tahun} {nama_klinik}','form_title'=>'Masuk ke Sistem','form_intro'=>'Gunakan email dan password akun klinik Anda.'];}
function login_copy_values():array{$saved=json_decode(setting('login_page_copy','{}'),true);$result=login_copy_defaults();if(is_array($saved))foreach($result as $k=>$v)if(isset($saved[$k])&&is_string($saved[$k]))$result[$k]=$saved[$k];return $result;}
function login_copy_validate(array $input):array{$limits=['title'=>120,'intro'=>800,'features'=>1600,'footer'=>250,'form_title'=>120,'form_intro'=>500];$values=[];foreach($limits as $key=>$limit){if(!is_string($input[$key]??null))throw new RuntimeException('Teks login tidak valid.');$text=trim(str_replace("\r\n","\n",$input[$key]));if(mb_strlen($text)>$limit||str_contains($text,"\0"))throw new RuntimeException('Teks '.$key.' terlalu panjang atau tidak valid.');if(in_array($key,['title','form_title'],true)&&$text==='')throw new RuntimeException('Judul login wajib diisi.');if($key==='features'&&count(array_filter(explode("\n",$text),fn($v)=>trim($v)!==''))>10)throw new RuntimeException('Maksimal 10 poin fitur.');$values[$key]=$text;}return $values;}
function login_copy_resolve(string $text,string $branchText=''):string{return strtr($text,['{nama_klinik}'=>clinic_name(),'{tahun}'=>date('Y'),'{cabang}'=>$branchText,'{daftar_cabang}'=>$branchText!==''?' — '.$branchText:'']);}